import{_ as r,C as a,c as s,o as n,a9 as l,G as t}from"./chunks/framework.ByXcQEbS.js";const c="/assets/plugin-in-firefox-shop.Cbk-r_tn.png",p="/assets/motrix-download-page.ogo2S8LI.png",g="/assets/aria2dmi-settings-general.DkLcYPhS.png",f="/assets/motrix-download-settings.ZhcbPegH.png",m="/assets/rpc-server-setting.q74HeI6D.png",d="/assets/aria2dmi-settings-example.Dg2SdkiY.png",u="/assets/download-example-qq.CL36ISDI.png",x="/assets/example-download-started.BcwRtVQV.png",_="/assets/exmaple-downloading.BBwS5eCH.png",h="/assets/example-download-completed.BYHRuKsN.png",D=JSON.parse('{"title":"为 Motrix 在 Firefox/Waterfox 上设置下载","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/common"},{"title":"为 Motrix 在 Firefox/Waterfox 上设置下载","link":"/common/personal-guides.motrix-setup-firefox"}]},"headers":[],"relativePath":"common/personal-guides.motrix-setup-firefox.md","filePath":"common/personal-guides.motrix-setup-firefox.md"}'),b={name:"common/personal-guides.motrix-setup-firefox.md"};function M(k,i,C,P,q,w){const e=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return n(),s("div",null,[i[0]||(i[0]=l('<h1 id="为-motrix-在-firefox-waterfox-上设置下载" tabindex="-1">为 Motrix 在 Firefox/Waterfox 上设置下载 <a class="header-anchor" href="#为-motrix-在-firefox-waterfox-上设置下载" aria-label="Permalink to &quot;为 Motrix 在 Firefox/Waterfox 上设置下载&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">提示</p><p>本章节的教程仅适用于使用 Firefox/Waterfox 等分支的浏览器用户。</p></div><p><a href="https://motrix.app/" target="_blank" rel="noreferrer">Motrix</a> 是一款基于 <a href="https://github.com/aria2/aria2" target="_blank" rel="noreferrer">aria2</a> 的下载器，其轻量化的界面和相对较好的性能博得了世界范围内许多网友的赞赏与青睐。目前，Motrix 仍然只对谷歌浏览器有<a href="https://github.com/gautamkrishnar/motrix-chrome-extension" target="_blank" rel="noreferrer">浏览器拓展支持</a>，而对于火狐浏览器及其分支缺乏公开的支持（唯一在火狐商店声称可用的兼容模块经个人测试同样无效）。</p><h2 id="_1-安装-aria2dmi-与-motrix" tabindex="-1">1. 安装 Aria2DMI 与 Motrix <a class="header-anchor" href="#_1-安装-aria2dmi-与-motrix" aria-label="Permalink to &quot;1. 安装 Aria2DMI 与 Motrix&quot;">​</a></h2><ul><li>前往 <a href="https://addons.mozilla.org/en-US/firefox/addon/aria2-integration/" target="_blank" rel="noreferrer">https://addons.mozilla.org/en-US/firefox/addon/aria2-integration/</a>，为你的浏览器安装这个拓展。</li></ul><figure><img src="'+c+'" alt="" tabindex="0"><figcaption></figcaption></figure><ul><li>前往 <a href="https://motrix.app/zh-CN/download" target="_blank" rel="noreferrer">Motrix 官网</a>，根据你的平台选择对应的安装包（也可选择通用版本的安装器，不过体积会稍大）。</li></ul><figure><img src="'+p+'" alt="" tabindex="0"><figcaption></figcaption></figure><div class="tip custom-block"><p class="custom-block-title">提示</p><p>其实 Motrix 也可以通过 <code>winget</code>、Chocolately、及 <code>scoop</code> 等命令行方式安装，这里不多作赘述。</p></div><h2 id="_2-打开-aria2dmi-的设置界面" tabindex="-1">2. 打开 Aria2DMI 的设置界面 <a class="header-anchor" href="#_2-打开-aria2dmi-的设置界面" aria-label="Permalink to &quot;2. 打开 Aria2DMI 的设置界面&quot;">​</a></h2><ul><li>通过右上角扩展 - 扩展列表，找到 Aria2 Download Manager Intergration（中文显示为“Aria2 下载器集成组件”）</li><li>在扩展右上角的三个点处，找到“选项”，点击进入该拓展的设置界面。</li><li>在“一般”一栏中，个人建议点选“新增右键菜单”、“传送 User-Agent 到 Aria2”这两个选项，可以提升使用体验。</li></ul><figure><img src="'+g+'" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="_3-进行进阶设置" tabindex="-1">3. 进行进阶设置 <a class="header-anchor" href="#_3-进行进阶设置" aria-label="Permalink to &quot;3. 进行进阶设置&quot;">​</a></h2><ul><li>回到 Motrix 界面，点击左下角第二个按钮，打开设置界面。</li><li>在“进阶设置”中找到 RPC 选项 - RPC 授权密钥，点击右侧的随机按钮产生一个。</li><li>接着 Motrix 会自动为你显示，将其复制。上方的端口号也请一并记忆。</li></ul><figure><img src="'+f+'" alt="" tabindex="0"><figcaption></figcaption></figure><ul><li>回到 Aria2DMI 的设置界面，点击“RPC 服务器”，再点击展开栏中的“默认服务器”。</li></ul><figure><img src="'+m+'" alt="" tabindex="0"><figcaption></figcaption></figure><ul><li>将先前的端口号和密钥一一填入此处，其他选项保持默认。</li></ul><figure><img src="'+d+'" alt="" tabindex="0"><figcaption></figcaption></figure><ul><li>点击右下角的蓝色按钮保存，关闭设置界面。</li></ul><h2 id="_4-测试下载" tabindex="-1">4. 测试下载 <a class="header-anchor" href="#_4-测试下载" aria-label="Permalink to &quot;4. 测试下载&quot;">​</a></h2><ul><li>随便找到一个可以下载的内容，既可以在右键菜单中手动唤起 Motrix，也可以直接点击下载链接。</li><li>以 QQ 官网为例，点击下载按钮后出现了如图所示的窗口。</li></ul><figure><img src="'+u+'" alt="" tabindex="0"><figcaption></figcaption></figure><ul><li>这里的下载路径留空则跟随 Motrix 的默认设置，若有需要可手动填写，也可在先前的浏览器设置中进行调整。</li><li>点击下载，即可静默拉起 Motrix，并在右下角弹出下载开始和完毕的提示。</li></ul><figure><img src="'+x+'" alt="" tabindex="0"><figcaption></figcaption></figure><figure><img src="'+_+'" alt="" tabindex="0"><figcaption></figcaption></figure><figure><img src="'+h+'" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="_5-大功告成" tabindex="-1">5. 大功告成！ <a class="header-anchor" href="#_5-大功告成" aria-label="Permalink to &quot;5. 大功告成！&quot;">​</a></h2><p>现在 Motrix 会接管所有下载请求，除非你点击取消。如果取消，浏览器将会使用自带的下载器进行下载。</p><details class="details custom-block"><summary>为什么重启电脑之后功能就失效了？</summary><p>这有可能是因为你没有设置 Motrix 的开机自启导致的。</p><p>如果下载器在线，Aria2DMI 的设置界面会弹出一条“服务器已连接”的提示。</p><p>按上文所述进入 Motrix 的设置界面，在基础设置 - 启动一栏找到“开机自动启动”，勾选即可。</p></details>',30)),t(e),t(o)])}const I=r(b,[["render",M]]);export{D as __pageData,I as default};
